 "content": "def transform(grid):
    """Restore the 8-masked rectangle using the grid's vertical row repetition."""
    h, w = len(grid), len(grid[0])
    masked = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not masked:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in masked), max(r for r, c in masked)
    c0, c1 = min(c for r, c in masked), max(c for r, c in masked)
    out = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            rr = h - 1 - r
            if 0 <= rr < h and grid[rr][c] != 8:
                row.append(grid[rr][c])
            else:
                # When reflection lands inside the masked band, select the
                # closest unmasked row by its visible (non-mask) pattern.
                candidates = [q for q in range(h) if grid[q][c] != 8 and q not in (r, rr)]
                q = min(candidates, key=lambda q: sum(
                    grid[q][x] != grid[r][x]
                    for x in range(w) if not (c0 <= x <= c1)
                ))
                row.append(grid[q][c])
        out.append(row)
    return out
"
}

